// AppTool A function tool in the OpenAI function-tool shape, plus `x-atmee`
// saying whether the avatar waits for the client's result.
type AppTool struct {
	// Description What the tool does and when to call it, 1 to 500 characters.
	Description string `json:"description"`

	// Name `^[a-z][a-z0-9_]{0,47}$`, unique in the session.
	//
	// Examples: show_slide
	Name string `json:"name"`

	// Parameters A JSON Schema for the arguments, with top-level `"type": "object"`; at most 4096 bytes of JSON. It must be valid JSON Schema 2020-12 (a `$schema` naming another dialect is refused), and a `$ref`, `$dynamicRef` or `$recursiveRef` anywhere in it must be a local pointer starting with `#`.
	Parameters map[string]interface{} `json:"parameters"`

	// Strict OpenAI's structured-arguments flag, accepted for compatibility and not used (arguments are checked against `parameters` either way).
	Strict *bool `json:"strict,omitempty"`

	// Type Always `function`.
	Type string `json:"type"`

	// XAtmee Whether the avatar waits for the client's result of a call, and for how long.
	XAtmee *AppToolOptions `json:"x-atmee,omitempty"`
}

// AppToolOptions Whether the avatar waits for the client's result of a call, and for how long.
type AppToolOptions struct {
	// Mode `notify` (default): the call is sent and the avatar goes on.
	// `await`: the avatar waits for the result (saying at most one
	// short filler line meanwhile) and answers from it.
	Mode *string `json:"mode,omitempty"`

	// TimeoutSeconds How long an `await` call waits, 1 to 28 (default 8).
	TimeoutSeconds *int `json:"timeoutSeconds,omitempty"`
}

// AppTools Functions the avatar may call in this session, and how to use them. Absent or null, the session has none.
type AppTools struct {
	// Instructions How and when the avatar uses the tools (and any app persona or rules), one text for all of them, at most 4000 characters.
	Instructions *string `json:"instructions,omitempty"`

	// Tools 1 to 30 tools, names unique, all of them at most 24576 bytes of
	// JSON. Names must not be one of Causeur's own tools (`web_search`,
	// `lookup`, `look_at_file`).
	Tools []AppTool `json:"tools"`
}

